st.title("🛡️ AI-Driven Cyber Threat Intelligence System")
st.caption(
    "Real-Time Network Intrusion Detection and Threat Scoring"
)

st.divider()


# --------------------------------------------------
# LOAD SECURITY ALERTS
# --------------------------------------------------

def load_alerts():


    """Load recorded security alerts from the CSV file."""

    if not ALERT_FILE.exists():
        return pd.DataFrame()

    try:
        return pd.read_csv(ALERT_FILE)
    except (pd.errors.EmptyDataError, pd.errors.ParserError):
        return pd.DataFrame()


alerts = load_alerts()


def load_telemetry():
    """Load all recorded live network flow telemetry."""

    if not TELEMETRY_FILE.exists():
        return pd.DataFrame()

    try:
        telemetry = pd.read_csv(TELEMETRY_FILE)

        if "prediction" in telemetry.columns:
            telemetry["prediction"] = (
                telemetry["prediction"]
                .fillna("UNKNOWN")
                .astype(str)
                .str.upper()
            )

        return telemetry

    except (
        pd.errors.EmptyDataError,
        pd.errors.ParserError,
        OSError
    ):
        return pd.DataFrame()


def load_unified_decisions():
    """
    Load flow-level decisions produced by the unified
    Random Forest and Isolation Forest decision engine.
    """

    if not UNIFIED_DECISIONS_FILE.exists():
        return pd.DataFrame()

    try:
        decisions = pd.read_csv(UNIFIED_DECISIONS_FILE)

        # Normalize decision labels for consistent display and filtering.
        if "final_prediction" in decisions.columns:
            decisions["final_prediction"] = (
                decisions["final_prediction"]
                .fillna("UNKNOWN")
                .astype(str)
                .str.strip()
                .str.upper()
            )

        if "threat_level" in decisions.columns:
            decisions["threat_level"] = (
                decisions["threat_level"]
                .fillna("UNSCORED")
                .astype(str)
                .str.strip()
                .str.upper()
            )

        return decisions

    except (
        pd.errors.EmptyDataError,
        pd.errors.ParserError,
        OSError
    ):
        return pd.DataFrame()


unified_decisions = load_unified_decisions()


# --------------------------------------------------
# DASHBOARD CONTROLS
