if st.button("🔄 Refresh Dashboard"):
    st.rerun()


# --------------------------------------------------
# LIVE NETWORK MONITORING OVERVIEW
# --------------------------------------------------

st.divider()

st.header("Live Network Monitoring Overview")

telemetry = load_telemetry()

if telemetry.empty:

    st.info(
        "No network telemetry available yet. "
        "Start the live network monitor to collect traffic."
    )

else:

    predictions = telemetry["prediction"]

    # Calculate actual recorded flow statistics.
    total_flows = len(telemetry)

    normal_flows = (
        predictions == "NORMAL"
    ).sum()

    anomalous_flows = (
        predictions == "ANOMALY"
    ).sum()

    detection_errors = (
        predictions == "ERROR"
    ).sum()

    # Exclude detection errors from the anomaly-rate denominator.
    successfully_classified = (
        normal_flows + anomalous_flows
    )

    if successfully_classified > 0:

        anomaly_rate = (
            anomalous_flows / successfully_classified
        ) * 100

    else:

        anomaly_rate = 0.0

    # Display the four main SOC metrics.
    col1, col2, col3, col4 = st.columns(4)

    col1.metric(
        "Total Recorded Flows",
        f"{total_flows:,}"
    )

    col2.metric(
        "Normal Flows",
        f"{normal_flows:,}"
    )

    col3.metric(
        "Anomalous Flows",
        f"{anomalous_flows:,}"
    )

    col4.metric(
        "Observed Anomaly Rate",
        f"{anomaly_rate:.2f}%"
    )

    st.caption(
        f"Detection errors: {detection_errors} | "
        "Anomalies represent deviations from the learned "
        "normal-traffic baseline, not confirmed attacks."
    )


    # DETECTION RESULT DISTRIBUTION


    import altair as alt

    st.divider()

    st.subheader("Network Traffic Detection Analysis")

    # Count the number of flows in each detection category.
    detection_chart_data = (
        telemetry.groupby("prediction")
        .size()
        .reset_index(name="Flow Count")
    )

    detection_chart = (
        alt.Chart(detection_chart_data)
        .mark_bar(
            cornerRadiusTopLeft=6,
            cornerRadiusTopRight=6
        )
        .encode(
            x=alt.X(
                "prediction:N",
                sort=["NORMAL", "ANOMALY", "ERROR"],
                title="Detection Result",
                axis=alt.Axis(
                    labelColor="#cbd5e1",
                    titleColor="#cbd5e1"
                )
            ),
            y=alt.Y(
                "Flow Count:Q",
                title="Number of Flows",
                axis=alt.Axis(
                    labelColor="#cbd5e1",
                    titleColor="#cbd5e1",
                    gridColor="#263650"
                )
            ),
            color=alt.Color(
                "prediction:N",
                scale=alt.Scale(
                    domain=["NORMAL", "ANOMALY", "ERROR"],
                    range=["#22c55e", "#f59e0b", "#ef4444"]
                ),
                legend=None
            ),
            tooltip=[
                "prediction",
                "Flow Count"
            ]
        )
        .properties(
            height=320,
            background="#080d19"
        )
        .configure_view(
            strokeOpacity=0
        )
    )

    st.altair_chart(
        detection_chart,
        use_container_width=True
    )


    # NETWORK PROTOCOL DISTRIBUTION


    st.divider()

    st.subheader("Network Protocol Distribution")

    if "protocol" in telemetry.columns:

        # Count the recorded flows for each protocol.
        protocol_chart_data = (
            telemetry["protocol"]
            .fillna("UNKNOWN")
            .astype(str)
            .str.upper()
            .value_counts()
            .rename_axis("Protocol")
            .reset_index(name="Flow Count")
        )

        protocol_chart = (
            alt.Chart(protocol_chart_data)
            .mark_bar(
                cornerRadiusTopLeft=6,
                cornerRadiusTopRight=6
            )
            .encode(
                x=alt.X(
                    "Protocol:N",
                    sort="-y",
                    title="Network Protocol"
                ),
                y=alt.Y(
                    "Flow Count:Q",
                    title="Number of Flows"
                ),
                color=alt.Color(
                    "Protocol:N",
                    legend=None
                ),
                tooltip=[
                    "Protocol",
                    "Flow Count"
                ]
            )
            .properties(
                height=320,
                background="#080d19"
            )
            .configure_view(
                strokeOpacity=0
            )
        )

        st.altair_chart(
            protocol_chart,
            use_container_width=True
        )

    else:


        st.info("Protocol information is not available.")


    # NETWORK TRAFFIC TRENDS


    st.divider()

    st.subheader("Network Traffic Trends")

    if "event_time" in telemetry.columns:

        # Convert timestamps into datetime values.
        trend_data = telemetry.copy()

        trend_data["event_time"] = pd.to_datetime(
            trend_data["event_time"],
            errors="coerce",
            utc=True
        )

        # Convert traffic volume into numeric values.
        trend_data["total_bytes"] = pd.to_numeric(
            trend_data["total_bytes"],
            errors="coerce"
        ).fillna(0)

        # Remove records without valid timestamps.
        trend_data = trend_data.dropna(
            subset=["event_time"]
        )

        if not trend_data.empty:

            # Group recorded flows into one-minute intervals.
            trend_data = (
                trend_data
                .groupby(
                    pd.Grouper(
                        key="event_time",
                        freq="1min"
                    )
                )
                .agg(
                    flow_count=("prediction", "size"),
                    total_bytes=("total_bytes", "sum")
                )
                .reset_index()
            )

            # Convert bytes into megabytes for readability.
            trend_data["traffic_mb"] = (
                trend_data["total_bytes"] / (1024 * 1024)
            )

            flow_col, traffic_col = st.columns(2)


            # FLOWS PER MINUTE


            with flow_col:

                st.markdown("**Flow Activity Per Minute**")

                flow_chart = (
                    alt.Chart(trend_data)
                    .mark_line(
                        point=True,
                        color="#38bdf8",
                        strokeWidth=3
                    )
                    .encode(
                        x=alt.X(
                            "event_time:T",
                            title="Time"
                        ),
                        y=alt.Y(
                            "flow_count:Q",
                            title="Recorded Flows"
                        ),
                        tooltip=[
                            "event_time:T",
                            "flow_count:Q"
                        ]
                    )
                    .properties(
                        height=300,
                        background="#080d19"
                    )
                    .configure_view(
                        strokeOpacity=0
                    )
                )

                st.altair_chart(
                    flow_chart,
                    use_container_width=True
                )


            # TRAFFIC VOLUME PER MINUTE


            with traffic_col:

                st.markdown("**Traffic Volume Per Minute**")

                traffic_chart = (
                    alt.Chart(trend_data)
                    .mark_area(
                        line={
                            "color": "#a78bfa",
                            "strokeWidth": 2
                        },
                        color="#a78bfa",
                        opacity=0.25
                    )
                    .encode(
                        x=alt.X(
                            "event_time:T",
                            title="Time"
                        ),
                        y=alt.Y(
                            "traffic_mb:Q",
                            title="Traffic Volume (MB)"
                        ),
                        tooltip=[
                            "event_time:T",
                            alt.Tooltip(
                                "traffic_mb:Q",
                                format=".4f"
                            )
                        ]
                    )
                    .properties(
                        height=300,
                        background="#080d19"
                    )
                    .configure_view(
                        strokeOpacity=0
                    )
                )

                st.altair_chart(
                    traffic_chart,
                    use_container_width=True
                )

        else:

            st.info("No valid timestamps available for traffic trends.")

    else:

        st.info("Timestamp information is unavailable.")


    # --------------------------------------------------
    # INTERACTIVE NETWORK FLOW MONITOR
    # --------------------------------------------------

    st.divider()

    st.subheader("Recent Network Flows")

    # Work on a copy so display transformations do not alter
    # the telemetry DataFrame used by the charts above.
    flow_table = telemetry.copy()

    # Normalize detection labels before filtering and styling.
    if "prediction" in flow_table.columns:
        flow_table["prediction"] = (
            flow_table["prediction"]
            .fillna("UNKNOWN")
            .astype(str)
            .str.upper()
        )
    else:
        flow_table["prediction"] = "UNKNOWN"

    # Treat failed telemetry records as ERROR even if their
    # prediction field is empty or contains another value.
    if "detection_status" in flow_table.columns:
        detection_status = (
            flow_table["detection_status"]
            .fillna("")
            .astype(str)
            .str.upper()
        )
        failed_records = ~detection_status.isin(
            ["", "SUCCESS", "OK", "COMPLETED"]
        )
        flow_table.loc[failed_records, "prediction"] = "ERROR"

    # Sort newest flows first when timestamps are available.
    if "event_time" in flow_table.columns:
        flow_table["event_time"] = pd.to_datetime(
            flow_table["event_time"],
            errors="coerce",
            utc=True
        )
        flow_table = flow_table.sort_values(
            "event_time",
            ascending=False,
            na_position="last"
        )

    # Interactive filter for the analyst.
    detection_filter = st.selectbox(
        "Filter Network Flows",
        options=["ALL", "NORMAL", "ANOMALY", "ERROR"],
        index=0,
        key="flow_detection_filter"
    )

    filtered_flows = flow_table.copy()

    if detection_filter != "ALL":
        filtered_flows = filtered_flows[
            filtered_flows["prediction"] == detection_filter
        ]

    # Display the fields that are available in the telemetry file.
    flow_columns = [
        "event_time",
        "source_ip",
        "source_port",
        "destination_ip",
        "destination_port",
        "protocol",
        "packet_count",
        "total_bytes",
        "prediction",
        "anomaly_score",
        "threat_score",
        "threat_level",
    ]

    available_flow_columns = [
        column
        for column in flow_columns
        if column in filtered_flows.columns
    ]

    # Show the 25 newest records matching the selected filter.
    recent_flows = filtered_flows[
        available_flow_columns
    ].head(25).copy()

    # Normalize display labels for consistent color styling.
    if "prediction" in recent_flows.columns:
        recent_flows["prediction"] = (
            recent_flows["prediction"]
            .fillna("UNKNOWN")
            .astype(str)
            .str.upper()
        )

    if "threat_level" in recent_flows.columns:
        recent_flows["threat_level"] = (
            recent_flows["threat_level"]
            .fillna("UNSCORED")
            .astype(str)
            .str.upper()
        )

    # Format timestamps for readability.
    if "event_time" in recent_flows.columns:
        recent_flows["event_time"] = (
            recent_flows["event_time"]
            .dt.strftime("%Y-%m-%d %H:%M:%S")
        )

    # Rename columns for dashboard presentation.
    recent_flows = recent_flows.rename(
        columns={
            "event_time": "Time",
            "source_ip": "Source IP",
            "source_port": "Source Port",
            "destination_ip": "Destination IP",
            "destination_port": "Destination Port",
            "protocol": "Protocol",
            "packet_count": "Packets",
            "total_bytes": "Total Bytes",
            "prediction": "Detection",
            "anomaly_score": "Anomaly Score",
            "threat_score": "Threat Score",
            "threat_level": "Threat Level",
        }
    )

    st.caption(
        f"Showing {len(recent_flows)} of "
        f"{len(filtered_flows):,} matching flows "
        "(maximum 25 rows). Anomaly scores are model scores, "
        "not probabilities."
    )

    if recent_flows.empty:
        st.info("No flows match the selected detection filter.")
    else:
        # Apply readable colors to detection outcomes.
        def style_detection(value):
            if value == "NORMAL":
                return "color: #4ade80; font-weight: bold;"
            if value == "ANOMALY":
                return "color: #fbbf24; font-weight: bold;"
            if value == "ERROR":
                return "color: #f87171; font-weight: bold;"
            return "color: #cbd5e1;"

        # Threat levels are application-defined priority bands.
        def style_threat(value):
            if value == "CRITICAL":
                return "color: #f87171; font-weight: bold;"
            if value == "HIGH":
                return "color: #fb923c; font-weight: bold;"
            if value == "MEDIUM":
                return "color: #fbbf24; font-weight: bold;"
            if value == "LOW":
                return "color: #4ade80; font-weight: bold;"
            return "color: #cbd5e1;"

        styled_flows = recent_flows.style

        # Format numeric columns for cleaner presentation.
        number_formats = {
            "Source Port": "{:.0f}",
            "Destination Port": "{:.0f}",
            "Packets": "{:,.0f}",
            "Total Bytes": "{:,.0f}",
            "Threat Score": "{:.0f}",
            "Anomaly Score": "{:.4f}",
        }

        styled_flows = styled_flows.format(
            number_formats,
            na_rep="—"
        )

        if "Detection" in recent_flows.columns:
            styled_flows = styled_flows.map(
                style_detection,
                subset=["Detection"]
            )

        if "Threat Level" in recent_flows.columns:
            styled_flows = styled_flows.map(
                style_threat,
                subset=["Threat Level"]
            )

        st.dataframe(
            styled_flows,
            use_container_width=True,
            hide_index=True
        )




# --------------------------------------------------
# UNIFIED AI DETECTION DECISIONS
# --------------------------------------------------

st.divider()
st.header("Unified AI Detection Decisions")

if unified_decisions.empty:
    st.info(
        "No unified decisions are available yet. "
        "Start the live network monitor to record combined RF and IF decisions."
    )
else:
    unified_view = unified_decisions.copy()

    # Provide safe defaults if an older CSV does not contain newer fields.
    if "final_prediction" not in unified_view.columns:
        unified_view["final_prediction"] = "UNKNOWN"

    unified_view["final_prediction"] = (
        unified_view["final_prediction"]
        .fillna("UNKNOWN")
        .astype(str)
        .str.strip()
        .str.upper()
    )

    # Read the explicit unified-engine flag when available.
    if "is_attack_flagged" in unified_view.columns:
        flagged_mask = (
            unified_view["is_attack_flagged"]
            .fillna(False)
            .astype(str)
            .str.strip()
            .str.lower()
            .isin(["true", "1", "yes"])
        )
    else:
        # Fallback for decision files created before this field existed.
        flagged_mask = unified_view["final_prediction"] != "BENIGN"

    if "rf_window_count" in unified_view.columns:
        rf_window_counts = pd.to_numeric(
            unified_view["rf_window_count"],
            errors="coerce"
        ).fillna(0)
    else:
        rf_window_counts = pd.Series(0, index=unified_view.index)

    if "if_is_anomaly" in unified_view.columns:
        if_anomaly_mask = (
            unified_view["if_is_anomaly"]
            .fillna(False)
            .astype(str)
            .str.strip()
            .str.lower()
            .isin(["true", "1", "yes"])
        )
    else:
        if_anomaly_mask = pd.Series(False, index=unified_view.index)

    # Summarize the decisions recorded by the unified engine.
    total_decisions = len(unified_view)
    benign_decisions = int(
        (unified_view["final_prediction"] == "BENIGN").sum()
    )
    flagged_decisions = int(flagged_mask.sum())
    total_rf_windows = int(rf_window_counts.sum())
    if_anomalous_flows = int(if_anomaly_mask.sum())

    metric_columns = st.columns(5)
    metric_columns[0].metric("Unified Decisions", f"{total_decisions:,}")
    metric_columns[1].metric("Flagged Decisions", f"{flagged_decisions:,}")
    metric_columns[2].metric("BENIGN Decisions", f"{benign_decisions:,}")
    metric_columns[3].metric("RF Windows", f"{total_rf_windows:,}")
    metric_columns[4].metric("IF Anomalies", f"{if_anomalous_flows:,}")

    st.caption(
        "These are outputs of the combined detection engine. "
        "A flagged decision is not, by itself, an independently confirmed attack. "
        "Threat scores and severity bands are application-defined."
    )

    # Allow the analyst to focus on flagged or benign decisions.
    unified_filter = st.selectbox(
        "Filter Unified Decisions",
        options=["ALL", "FLAGGED", "BENIGN"],
        key="unified_decision_filter"
    )

    filtered_decisions = unified_view.copy()

    if unified_filter == "FLAGGED":
        filtered_decisions = filtered_decisions.loc[flagged_mask]
    elif unified_filter == "BENIGN":
        filtered_decisions = filtered_decisions[
            filtered_decisions["final_prediction"] == "BENIGN"
        ]

    # Sort newest decisions first when event timestamps are available.
    if "event_time" in filtered_decisions.columns:
        filtered_decisions["_event_time_sort"] = pd.to_datetime(
            filtered_decisions["event_time"],
            errors="coerce",
            utc=True
        )
        filtered_decisions = filtered_decisions.sort_values(
            "_event_time_sort",
            ascending=False,
            na_position="last"
        )
        filtered_decisions["event_time"] = (
            filtered_decisions["_event_time_sort"]
            .dt.strftime("%Y-%m-%d %H:%M:%S")
        )
        filtered_decisions = filtered_decisions.drop(
            columns=["_event_time_sort"]
        )

    # Show the final decision alongside the evidence from both models.
    unified_display_columns = [
        "event_time",
        "source_ip",
        "source_port",
        "destination_ip",
        "destination_port",
        "protocol",
        "final_prediction",
        "threat_score",
        "threat_level",
        "evidence_status",
        "rf_prediction",
        "rf_window_count",
        "rf_flagged_window_count",
        "if_prediction",
        "if_is_anomaly",
    ]

    available_unified_columns = [
        column
        for column in unified_display_columns
        if column in filtered_decisions.columns
    ]

    recent_decisions = (
        filtered_decisions[available_unified_columns]
        .head(30)
        .copy()
    )

    recent_decisions = recent_decisions.rename(
        columns={
            "event_time": "Time",
            "source_ip": "Source IP",
            "source_port": "Source Port",
            "destination_ip": "Destination IP",
            "destination_port": "Destination Port",
            "protocol": "Protocol",
            "final_prediction": "Final Decision",
            "threat_score": "Threat Score",
            "threat_level": "Threat Level",
            "evidence_status": "Evidence Status",
            "rf_prediction": "RF Prediction",
            "rf_window_count": "RF Windows",
            "rf_flagged_window_count": "RF Flagged Windows",
            "if_prediction": "IF Prediction",
            "if_is_anomaly": "IF Anomaly",
        }
    )

    st.caption(
        f"Showing {len(recent_decisions)} of "
        f"{len(filtered_decisions):,} matching unified decisions "
        "(maximum 30 rows)."
    )

    if recent_decisions.empty:
        st.info("No unified decisions match the selected filter.")
    else:
        # Format numeric fields without changing the underlying CSV data.
        number_formats = {
            "Source Port": "{:.0f}",
            "Destination Port": "{:.0f}",
            "Threat Score": "{:.0f}",
            "RF Windows": "{:.0f}",
            "RF Flagged Windows": "{:.0f}",
        }

        st.dataframe(
            recent_decisions.style.format(
                number_formats,
                na_rep="—"
            ),
            use_container_width=True,
            hide_index=True
        )


# --------------------------------------------------
# SECURITY ALERTS AND INVESTIGATION
# --------------------------------------------------

st.divider()
st.header("Security Alerts & Investigation")

# Keep a copy of the CSV row positions so review-status updates
# can be written back to the corresponding alert record.
alerts = alerts.copy()

if not alerts.empty:
    alerts["_alert_row"] = range(len(alerts))
else:
    alerts["_alert_row"] = pd.Series(dtype="int64")

# Supply defaults for older alert files that may not contain
# every field introduced by later versions of the alert manager.
alert_defaults = {
    "alert_time": pd.NaT,
    "source_ip": "UNKNOWN",
    "source_port": None,
    "destination_ip": "UNKNOWN",
    "destination_port": None,
    "protocol": "UNKNOWN",
    "anomaly_score": None,
    "decision_score": None,
    "raw_score": None,
    "threat_score": 0,
    "threat_level": "UNSCORED",
    "score_reasons": "",
    "baseline_percentiles": "",
    "status": "UNREVIEWED",
}

for column, default_value in alert_defaults.items():
    if column not in alerts.columns:
        alerts[column] = default_value

if not alerts.empty:
    alerts["alert_time"] = pd.to_datetime(
        alerts["alert_time"],
        errors="coerce"
    )

    for numeric_column in [
        "source_port",
        "destination_port",
        "anomaly_score",
        "decision_score",
        "raw_score",
        "threat_score",
    ]:
        alerts[numeric_column] = pd.to_numeric(
            alerts[numeric_column],
            errors="coerce"
        )

    alerts["threat_level"] = (
        alerts["threat_level"]
        .fillna("UNSCORED")
        .astype(str)
        .str.strip()
        .str.upper()
    )

    alerts["status"] = (
        alerts["status"]
        .fillna("UNREVIEWED")
        .astype(str)
        .str.strip()
        .str.upper()
        .replace("", "UNREVIEWED")
    )

    # Newest alerts appear first; _alert_row retains the CSV row identity.
    alerts = alerts.sort_values(
        "alert_time",
        ascending=False,
        na_position="last"
    )

# --------------------------------------------------
# ALERT SEVERITY SUMMARY
# --------------------------------------------------

total_alerts = len(alerts)
critical_alerts = int((alerts["threat_level"] == "CRITICAL").sum())
high_alerts = int((alerts["threat_level"] == "HIGH").sum())
medium_alerts = int((alerts["threat_level"] == "MEDIUM").sum())
unreviewed_alerts = int((alerts["status"] == "UNREVIEWED").sum())

metric_columns = st.columns(5)
metric_columns[0].metric("Total Alerts", f"{total_alerts:,}")
metric_columns[1].metric("Critical", f"{critical_alerts:,}")
metric_columns[2].metric("High", f"{high_alerts:,}")
metric_columns[3].metric("Medium", f"{medium_alerts:,}")
metric_columns[4].metric("Unreviewed", f"{unreviewed_alerts:,}")

if alerts.empty:
    st.info(
        "No security alerts have been recorded yet. "
        "Start the live network monitor to generate alert records."
    )
else:
    # --------------------------------------------------
    # THREAT LEVEL DISTRIBUTION
    # --------------------------------------------------

    st.subheader("Threat Level Distribution")

    threat_order = ["LOW", "MEDIUM", "HIGH", "CRITICAL", "UNSCORED"]
    threat_counts = (
        alerts["threat_level"]
        .value_counts()
        .reindex(threat_order, fill_value=0)
    )

    chart_col, guide_col = st.columns([2, 1])

    with chart_col:
        st.bar_chart(
            threat_counts,
            x_label="Threat Level",
            y_label="Number of Alerts"
        )

    with guide_col:
        st.markdown("**Configured threat severity guide**")
        st.write("🟢 LOW: 0–24")
        st.write("🟡 MEDIUM: 25–49")
        st.write("🟠 HIGH: 50–74")
        st.write("🔴 CRITICAL: 75–100")
        st.caption(
            "These are application-defined priority bands, "
            "not standardized risk ratings or attack probabilities."
        )

    st.divider()

    # --------------------------------------------------
    # ALERT SEARCH AND FILTERS
    # --------------------------------------------------

    st.subheader("Alert Search & Filters")

    filter_col, status_col, search_col = st.columns([1, 1, 2])

    with filter_col:
        severity_filter = st.selectbox(
            "Threat severity",
            options=[
                "ALL",
                "CRITICAL",
                "HIGH",
                "MEDIUM",
                "LOW",
                "UNSCORED",
            ],
            key="alert_severity_filter",
        )

    with status_col:
        review_filter = st.selectbox(
            "Review status",
            options=["ALL", "UNREVIEWED", "REVIEWED"],
            key="alert_review_filter",
        )

    with search_col:
        alert_search = st.text_input(
            "Search alerts",
            placeholder="Search IP address, protocol, or alert details...",
            key="alert_search_query",
        )

    filtered_alerts = alerts.copy()

    if severity_filter != "ALL":
        filtered_alerts = filtered_alerts[
            filtered_alerts["threat_level"] == severity_filter
        ]

    if review_filter != "ALL":
        filtered_alerts = filtered_alerts[
            filtered_alerts["status"] == review_filter
        ]

    if alert_search.strip():
        searchable_columns = [
            column
            for column in [
                "source_ip",
                "destination_ip",
                "protocol",
                "threat_level",
                "status",
                "score_reasons",
            ]
            if column in filtered_alerts.columns
        ]

        if searchable_columns:
            searchable_text = (
                filtered_alerts[searchable_columns]
                .fillna("")
                .astype(str)
                .agg(" ".join, axis=1)
            )

            filtered_alerts = filtered_alerts[
                searchable_text.str.contains(
                    alert_search.strip(),
                    case=False,
                    regex=False,
                    na=False,
                )
            ]

    # --------------------------------------------------
    # RECENT ALERTS TABLE
    # --------------------------------------------------

    st.subheader("Security Alert Records")

    alert_display_columns = [
        "alert_time",
        "source_ip",
        "source_port",
        "destination_ip",
        "destination_port",
        "protocol",
        "anomaly_score",
        "threat_score",
        "threat_level",
        "status",
    ]

    available_alert_columns = [
        column
        for column in alert_display_columns
        if column in filtered_alerts.columns
    ]

    recent_alerts = filtered_alerts[
        available_alert_columns
    ].head(25).copy()

    if "alert_time" in recent_alerts.columns:
        recent_alerts["alert_time"] = (
            recent_alerts["alert_time"]
            .dt.strftime("%Y-%m-%d %H:%M:%S")
        )

    recent_alerts = recent_alerts.rename(
        columns={
            "alert_time": "Alert Time",
            "source_ip": "Source IP",
            "source_port": "Source Port",
            "destination_ip": "Destination IP",
            "destination_port": "Destination Port",
            "protocol": "Protocol",
            "anomaly_score": "Anomaly Score",
            "threat_score": "Threat Score",
            "threat_level": "Threat Level",
            "status": "Review Status",
        }
    )

    st.caption(
        f"Showing {len(recent_alerts)} of "
        f"{len(filtered_alerts):,} matching alerts "
        "(maximum 25 rows)."
    )

    if recent_alerts.empty:
        st.info("No alerts match the selected filters.")
    else:
        def style_alert_severity(value):
            severity_styles = {
                "CRITICAL": "color: #f87171; font-weight: bold;",
                "HIGH": "color: #fb923c; font-weight: bold;",
                "MEDIUM": "color: #fbbf24; font-weight: bold;",
                "LOW": "color: #4ade80; font-weight: bold;",
            }
            return severity_styles.get(value, "color: #cbd5e1;")

        def style_review_status(value):
            if value == "REVIEWED":
                return "color: #4ade80; font-weight: bold;"
            if value == "UNREVIEWED":
                return "color: #fbbf24; font-weight: bold;"
            return "color: #cbd5e1;"

        styled_alerts = recent_alerts.style.format(
            {
                "Source Port": "{:.0f}",
                "Destination Port": "{:.0f}",
                "Anomaly Score": "{:.4f}",
                "Threat Score": "{:.0f}",
            },
            na_rep="—",
        )

        if "Threat Level" in recent_alerts.columns:
            styled_alerts = styled_alerts.map(
                style_alert_severity,
                subset=["Threat Level"],
            )

        if "Review Status" in recent_alerts.columns:
            styled_alerts = styled_alerts.map(
                style_review_status,
                subset=["Review Status"],
            )

        st.dataframe(
            styled_alerts,
            use_container_width=True,
            hide_index=True,
        )

    # --------------------------------------------------
    # ALERT INVESTIGATION DETAILS
    # --------------------------------------------------

    st.divider()
    st.subheader("Alert Investigation")

    if filtered_alerts.empty:
        st.info("Choose different filters to investigate an alert.")
    else:
        alert_row_options = filtered_alerts["_alert_row"].tolist()

        def format_alert_option(row_number):
            selected = alerts.loc[
                alerts["_alert_row"] == row_number
            ].iloc[0]

            alert_time = selected.get("alert_time")
            if pd.isna(alert_time):
                time_label = "Unknown time"
            else:
                time_label = alert_time.strftime("%Y-%m-%d %H:%M:%S")

            return (
                f"{time_label} | "
                f"{selected.get('threat_level', 'UNSCORED')} | "
                f"{selected.get('source_ip', 'Unknown source')} → "
                f"{selected.get('destination_ip', 'Unknown destination')}"
            )

        selected_alert_row = st.selectbox(
            "Select an alert to investigate",
            options=alert_row_options,
            format_func=format_alert_option,
            key="selected_alert_row",
        )

        selected_alert = alerts.loc[
            alerts["_alert_row"] == selected_alert_row
        ].iloc[0]

        detail_col1, detail_col2, detail_col3 = st.columns(3)

        detail_col1.metric(
            "Threat Score",
            (
                "—"
                if pd.isna(selected_alert["threat_score"])
                else f"{selected_alert['threat_score']:.0f}/100"
            ),
        )
        detail_col2.metric(
            "Threat Level",
            str(selected_alert["threat_level"]),
        )
        detail_col3.metric(
            "Review Status",
            str(selected_alert["status"]),
        )

        st.markdown("**Network and detection details**")

        details = {
            "Alert Time": (
                "Unknown"
                if pd.isna(selected_alert["alert_time"])
                else selected_alert["alert_time"].strftime(
                    "%Y-%m-%d %H:%M:%S"
                )
            ),
            "Source IP": selected_alert.get("source_ip", "UNKNOWN"),
            "Source Port": selected_alert.get("source_port"),
            "Destination IP": selected_alert.get(
                "destination_ip", "UNKNOWN"
            ),
            "Destination Port": selected_alert.get("destination_port"),
            "Protocol": selected_alert.get("protocol", "UNKNOWN"),
            "Anomaly Score": selected_alert.get("anomaly_score"),
            "Decision Score": selected_alert.get("decision_score"),
            "Raw Model Score": selected_alert.get("raw_score"),
        }
        st.json(details)

        st.markdown("**Threat scoring explanation**")
        reasons = selected_alert.get("score_reasons", "")
        if pd.notna(reasons) and str(reasons).strip():
            st.code(str(reasons), language="text")
        else:
            st.write("No scoring explanation is available for this record.")

        baseline_details = selected_alert.get("baseline_percentiles", "")
        if pd.notna(baseline_details) and str(baseline_details).strip():
            with st.expander("View baseline percentile information"):
                st.code(str(baseline_details), language="json")

        # --------------------------------------------------
        # REVIEW STATUS MANAGEMENT
        # --------------------------------------------------

        st.markdown("**Alert review action**")

        current_status = str(
            selected_alert.get("status", "UNREVIEWED")
        ).upper()

        if current_status == "REVIEWED":
            target_status = "UNREVIEWED"
            action_label = "Reopen Alert"
        else:
            target_status = "REVIEWED"
            action_label = "Mark as Reviewed"

        if st.button(
            action_label,
            key=f"review_alert_{selected_alert_row}",
        ):
            try:
                # Reload the latest CSV before updating so alerts appended
                # since the dashboard's last refresh are not discarded.
                latest_alerts = pd.read_csv(ALERT_FILE)

                if "status" not in latest_alerts.columns:
                    latest_alerts["status"] = "UNREVIEWED"

                if (
                    selected_alert_row < 0
                    or selected_alert_row >= len(latest_alerts)
                ):
                    st.error(
                        "This alert record changed. Refresh the dashboard "
                        "and select the alert again."
                    )
                else:
                    latest_alerts.loc[
                        selected_alert_row, "status"
                    ] = target_status

                    latest_alerts.to_csv(
                        ALERT_FILE,
                        index=False,
                    )

                    st.success(
                        f"Alert status updated to {target_status}."
                    )
                    st.rerun()

            except (OSError, pd.errors.ParserError, pd.errors.EmptyDataError) as error:
                st.error(f"Could not update the alert review status: {error}")


# SUPERVISED RANDOM FOREST PREDICTION


import json
from urllib.request import Request, urlopen
from urllib.error import HTTPError, URLError

st.divider()

st.header("Supervised AI Attack Classification")

st.write(
    "Use the trained Random Forest model to classify "
    "a CICIoT2023 test sample into its traffic category."
)

# Paths to the existing processed test dataset.
X_TEST_FILE = PROJECT_ROOT / "dataset" / "processed" / "X_test.csv"
Y_TEST_FILE = PROJECT_ROOT / "dataset" / "processed" / "y_test.csv"

API_URL = "http://127.0.0.1:8000/predict"


@st.cache_data
def load_test_dataset():
    """Load the test features and their actual labels."""
    X = pd.read_csv(X_TEST_FILE)
    y = pd.read_csv(Y_TEST_FILE)

    return X, y


if not X_TEST_FILE.exists() or not Y_TEST_FILE.exists():

    st.error("Test dataset files could not be found.")

else:

    try:
        X_test, y_test = load_test_dataset()

        if len(X_test) != len(y_test):
            st.error("Feature and label datasets have different row counts.")

        elif X_test.shape[1] != 39:
            st.error(
                f"Expected 39 model features, but found "
                f"{X_test.shape[1]}. Check X_test.csv."
            )

        else:

            st.success(
                f"Test dataset loaded: {len(X_test):,} samples "
                f"and {X_test.shape[1]} features."
            )

            # Let the user choose a test sample.
            sample_index = st.number_input(
                "Select test sample index",
                min_value=0,
                max_value=len(X_test) - 1,
                value=0,
                step=1
            )

            sample = X_test.iloc[int(sample_index)]

            actual_label = str(
                y_test.iloc[int(sample_index), 0]
            )

            with st.expander("View the selected sample's 39 features"):
                st.dataframe(
                    sample.to_frame(name="Feature Value"),
                    use_container_width=True
                )

            st.write(f"**Actual dataset label:** `{actual_label}`")

            if st.button("Run Random Forest Classification"):

                # Convert NumPy values to ordinary Python floats
                # so they can be sent as valid JSON.
                features = {
                    str(name): float(value)
                    for name, value in sample.items()
                }

                payload = json.dumps({
                    "features": features
                }).encode("utf-8")

                request = Request(
                    API_URL,
                    data=payload,
                    headers={"Content-Type": "application/json"},
                    method="POST"
                )

                try:
                    with st.spinner("Running AI classification..."):

                        with urlopen(request, timeout=30) as response:
                            result = json.loads(
                                response.read().decode("utf-8")
                            )

                    predicted_label = str(
                        result.get("prediction", "Unknown")
                    )

                    confidence = result.get("confidence")
                    threat_score = result.get("threat_score")
                    threat_level = result.get("threat_level")

                    st.subheader("Classification Result")

                    col1, col2, col3 = st.columns(3)

                    col1.metric(
                        "Predicted Class",
                        predicted_label
                    )

                    if confidence is not None:
                        col2.metric(
                            "Model Confidence",
                            f"{float(confidence):.4f}"
                        )

                    if threat_score is not None:
                        col3.metric(
                            "Threat Score",
                            f"{float(threat_score):.0f}/100"
                        )

                    if threat_level is not None:
                        st.write(
                            f"**Threat Level:** {threat_level}"
                        )

                    # Compare the prediction with the known test label.
                    if predicted_label == actual_label:

                        st.success(
                            "Prediction matches the actual dataset label."
                        )

                    else:

                        st.warning(
                            "Prediction differs from the actual dataset label."
                        )

                except HTTPError as error:

                    details = error.read().decode("utf-8")

                    st.error(
                        f"API returned HTTP {error.code}: {details}"
                    )

                except URLError as error:

                    st.error(
                        f"Could not connect to the prediction API: {error}"
                    )

                except (ValueError, TypeError) as error:

                    st.error(
                        f"Could not process the prediction result: {error}"
                    )

    except Exception as error:

        st.error(f"Could not load the test dataset: {error}")


# RANDOM FOREST MODEL EVALUATION


st.divider()

st.header("Random Forest Model Evaluation")

st.write(
    "Comparison of the baseline and improved Random Forest "
    "models using the held-out CICIoT2023 test dataset."
)

# Previously measured evaluation results.
# Values are percentages, not fractions.
evaluation_data = {
    "Metric": [
        "Accuracy",
        "Macro Precision",
        "Macro Recall",
        "Macro F1-Score",
        "Weighted F1-Score"
    ],
    "Baseline Random Forest": [
        75.61, 63.92, 56.84, 57.72, 75.10
    ],
    "Improved Random Forest": [
        76.72, 62.88, 58.93, 59.03, 76.11
    ]
}

evaluation_df = pd.DataFrame(evaluation_data)

# Calculate the improvement in percentage points.
evaluation_df["Change (percentage points)"] = (
    evaluation_df["Improved Random Forest"]
    - evaluation_df["Baseline Random Forest"]
).round(2)

# Display the selected model's key results.
st.subheader("Selected Model: Improved Random Forest")

metric1, metric2, metric3 = st.columns(3)

metric1.metric("Accuracy", "76.72%")
metric2.metric("Macro F1-Score", "59.03%")
metric3.metric("Weighted F1-Score", "76.11%")

# Display the full comparison.
st.subheader("Baseline vs Improved Model")

st.dataframe(
    evaluation_df.style.format({
        "Baseline Random Forest": "{:.2f}%",
        "Improved Random Forest": "{:.2f}%",
        "Change (percentage points)": "{:+.2f}"
    }),
    use_container_width=True,
    hide_index=True
)

# Visual comparison of the evaluation metrics.
st.subheader("Performance Comparison")

chart_df = evaluation_df.set_index("Metric")[
    [
        "Baseline Random Forest",
        "Improved Random Forest"
    ]
]


# Create a grouped bar chart instead of stacked bars.
import altair as alt

# Convert the evaluation table into long format.
chart_data = evaluation_df[
    ["Metric", "Baseline Random Forest", "Improved Random Forest"]
].melt(
    id_vars="Metric",
    var_name="Model",
    value_name="Score"
)

# Create side-by-side bars for each evaluation metric.
chart = alt.Chart(chart_data).mark_bar().encode(
    x=alt.X("Metric:N", title="Evaluation Metric"),
    xOffset="Model:N",
    y=alt.Y(
        "Score:Q",
        title="Performance (%)",
        scale=alt.Scale(domain=[0, 100])
    ),
    color=alt.Color("Model:N", title="Model"),
    tooltip=[
        "Metric",
        "Model",
        alt.Tooltip("Score:Q", format=".2f")
    ]
).properties(
    height=400
)

st.altair_chart(chart, use_container_width=True)

# Explain the model selection.
st.subheader("Model Selection Analysis")

st.markdown(
    """
    The improved Random Forest was selected because it achieved:

    - Higher accuracy than the baseline model.
    - Higher macro recall.
    - Higher macro F1-score.
    - Higher weighted F1-score.

    Macro precision decreased slightly, so the improvement is
    not uniform across all evaluation metrics.
    """
)

st.info(
    "Evaluation scope: one cleaned CICIoT2023 source file "
    "(Merged01.csv), with a stratified 80/20 train-test split. "
    "These results should not be interpreted as performance "
    "on every CICIoT2023 file or on live network traffic."
)


